import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import API from '../api/axios';
import { Megaphone, AlertTriangle, Calendar, Search } from 'lucide-react';

const Dashboard = () => {
  const [announcements, setAnnouncements] = useState([]);
  const user = JSON.parse(localStorage.getItem('user'));

  useEffect(() => {
    API.get('/admin/announcements')
      .then(res => setAnnouncements(res.data))
      .catch(err => console.error(err));
  }, []);

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-8">
      <div className="bg-gradient-to-r from-sky-600 to-indigo-700 rounded-2xl p-6 text-white shadow-lg">
        <h1 className="text-3xl font-extrabold">Welcome back, {user?.name}!</h1>
        <p className="mt-1 text-sky-100">Roll/ID: {user?.rollNo} | Campus Digital Portal</p>
      </div>

      {/* Quick Action Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Link to="/new-complaint" className="bg-white p-6 rounded-xl shadow-md border hover:border-sky-500 transition group">
          <AlertTriangle className="w-8 h-8 text-amber-500 mb-3 group-hover:scale-110 transition" />
          <h3 className="font-bold text-lg text-slate-800">Raise Maintenance Complaint</h3>
          <p className="text-sm text-slate-500 mt-1">Report plumbing, electrical or hostel issues with photo proof.</p>
        </Link>

        <Link to="/book-room" className="bg-white p-6 rounded-xl shadow-md border hover:border-sky-500 transition group">
          <Calendar className="w-8 h-8 text-sky-500 mb-3 group-hover:scale-110 transition" />
          <h3 className="font-bold text-lg text-slate-800">Book Lab / Classroom</h3>
          <p className="text-sm text-slate-500 mt-1">Check availability and request room approvals instantly.</p>
        </Link>

        <Link to="/lost-found" className="bg-white p-6 rounded-xl shadow-md border hover:border-sky-500 transition group">
          <Search className="w-8 h-8 text-emerald-500 mb-3 group-hover:scale-110 transition" />
          <h3 className="font-bold text-lg text-slate-800">Lost & Found Portal</h3>
          <p className="text-sm text-slate-500 mt-1">Post lost belongings or return items found on campus.</p>
        </Link>
      </div>

      {/* Campus Announcements */}
      <div className="bg-white p-6 rounded-xl shadow-md border border-slate-200">
        <div className="flex items-center space-x-2 border-b pb-4 mb-4">
          <Megaphone className="w-6 h-6 text-sky-600" />
          <h2 className="text-xl font-bold text-slate-800">Campus Announcements</h2>
        </div>

        {announcements.length === 0 ? (
          <p className="text-slate-500 text-sm">No announcements posted yet.</p>
        ) : (
          <div className="space-y-4">
            {announcements.map((item) => (
              <div key={item._id} className="p-4 bg-slate-50 rounded-lg border-l-4 border-sky-500">
                <h4 className="font-bold text-slate-900">{item.title}</h4>
                <p className="text-sm text-slate-600 mt-1">{item.description}</p>
                <span className="text-xs text-slate-400 mt-2 block">
                  Posted on {new Date(item.createdAt).toLocaleDateString()}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
